#pragma once

#include <pnes/video.hpp>
#include "../../chr/chr.h"     // CHR tile indices, generated by blobman

/*
 * One ppu::ChrWindow per packed set this game banks in: where the set starts
 * in character ROM, and the tile index the PPU sees it at once it is there.
 * Every tile reference in the demo goes through one of these -- a tile is
 * named by where the packer put it (blob::<entry>::lma::<include>) and turned
 * into what the hardware reads by the window holding it.
 *
 * THE PPU ORIGINS BELOW ARE THIS GAME'S DECISION, written out rather than
 * derived. blobman says where art was packed; where it is banked is the
 * banking plan in level.cpp/title.cpp, and these have to agree with the
 * registers those write -- see the comment above their SwitchCHRBank calls
 * for the chrMode::fineFirst window map. Nothing checks that they do.
 *
 * An origin is one byte because a pattern table is not part of a tile index:
 * PPU $0400 and $1400 are both origin 0x40, and which table a fetch comes
 * from is ppu::ctrl::BG_ADDR / SPRITE_ADDR (or bit 0 of an 8x16 sprite's tile
 * byte). That is why normalSprites, banked at PPU $1000, has origin 0x00.
 *
 * Two sets sharing one PPU window is the ordinary case, not a conflict:
 * staticLevelTiles and ui are alternatives for the $0400 window, and
 * whichever was banked last is the one a translation through it is true of.
 */
namespace windows {
    /// CHR tiles are 16 bytes, so an entry's byte position in the image
    /// divides down into the tile index ppu::ChrWindow wants. blobman emits
    /// `lma::` per include but the entry's own origin only in bytes, as
    /// __lma, hence the division here.
    constexpr u16 kTileBytes = 16;

    /// R2, PPU $0000 under chrMode::fineFirst.
    inline constexpr ppu::ChrWindow dynamicLevelTiles{
        blob::dynamicLevelTiles::__lma / kTileBytes, 0x00};

    /// R3, PPU $0400. Shares the window with ::ui.
    inline constexpr ppu::ChrWindow staticLevelTiles{
        blob::staticLevelTiles::__lma / kTileBytes, 0x40};

    /// R3, PPU $0400. Shares the window with ::staticLevelTiles.
    inline constexpr ppu::ChrWindow ui{
        blob::ui::__lma / kTileBytes, 0x40};

    /// R0, PPU $1000 -- a 2 KiB window, and the sprite half, so origin 0x00
    /// with the table coming from PPUCTRL.
    inline constexpr ppu::ChrWindow normalSprites{
        blob::normalSprites::__lma / kTileBytes, 0x00};
}
